<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Create New Exam</h1><p>Define and manage examination periods.</p></div></header><div class="split-layout"><form class="module-card" method="post" action="<?= url('/admin/exams') ?>"><?= csrf_field() ?><header class="module-card__header"><h2>Add New Exam</h2></header><div class="module-card__body"><div class="module-form-grid"><div class="module-field"><label>Examination Name</label><input class="module-input" name="examname" required></div><div class="module-field"><label>Start Date</label><input class="module-input" type="date" name="startdate" required></div><div class="module-field"><label>End Date</label><input class="module-input" type="date" name="enddate" required></div></div><button class="btn btn--primary">Save Exam</button></div></form><section class="module-card"><header class="module-card__header"><h2>Existing Exams</h2></header><div class="module-card__body"><table class="data-table"><thead><tr><th>Name</th><th>Start</th><th>End</th><th></th></tr></thead><tbody><?php foreach($exams as$e):?><tr><td><?= e($e['name']) ?></td><td><?= e($e['start_date']) ?></td><td><?= e($e['end_date']) ?></td><td><form method="post" action="<?= url('/admin/exams/'.$e['id'].'/delete') ?>"><?= csrf_field() ?><button class="btn btn--danger" onclick="return confirm('Delete exam and its marks?')">Delete</button></form></td></tr><?php endforeach ?></tbody></table></div></section></div></div></div></main>
